#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Non-secret values (address, MAC, username) are remembered here so re-runs
# offer them as defaults. No secret is ever written to this file.
ENV_FILE="$(cd "$(dirname "$0")" && pwd)/.jarvis.env"
SSH_DIR="$HOME/.ssh"
SSH_CONFIG="$SSH_DIR/config"
SSH_KEY="$SSH_DIR/id_ed25519"
PI_NAME="jarvis.local"

usage() {
  printf '\n%sUsage:%s ./jarvis-wizard.sh <stage>\n\n' "$BOLD" "$RESET"
  printf '  connect   find the Pi, fix its address, set up and test SSH (guide step 4)\n'
  printf '  tailscale reach jarvis from anywhere over Tailscale (guide step 7)\n'
  printf '  secrets   Telegram bot, your Telegram ID, Jarvis'"'"'s OpenRouter key (guide step 9)\n\n'
  printf '  To start, run:  %s./jarvis-wizard.sh connect%s\n\n' "$BOLD" "$RESET"
}

# lookup_ip NAME prints the IPv4 address NAME resolves to via mDNS, if any.
lookup_ip() {
  local out
  if command -v dscacheutil >/dev/null 2>&1; then
    out=$(dscacheutil -q host -a name "$1" 2>/dev/null | awk '/^ip_address:/ {print $2; exit}')
    [[ -n "$out" ]] && { printf '%s' "$out"; return 0; }
  fi
  out=$(ping -c1 -W2 "$1" 2>/dev/null | sed -nE '1s/^PING [^(]*\(([0-9.]+)\).*/\1/p') || true
  [[ -n "$out" ]] && printf '%s' "$out"
}

# mac_of IP prints the MAC address of IP from the ARP table, zero-padded.
mac_of() {
  ping -c1 -W2 "$1" >/dev/null 2>&1 || true
  arp -n "$1" 2>/dev/null | awk '{for (i=1;i<=NF;i++) if ($i=="at") {print $(i+1); exit}}' \
    | awk -F: 'NF==6 {for (i=1;i<=6;i++) printf "%s%02s", (i>1?":":""), $i; print ""}' | tr ' ' 0
}

# ssh_open HOST: is something answering on port 22?
ssh_open() { nc -z -w 2 "$1" 22 >/dev/null 2>&1; }

# fp_of: fingerprints of the key lines on stdin ("type base64" per line).
fp_of() { ssh-keygen -lf - 2>/dev/null | awk '{print $2}'; }

connect() {

TOTAL_STAGES=6

banner "Connect to jarvis"

# ── 1. Wait for boot ──────────────────────────────────────────────────────
stage "Wait for the Pi to boot"
say "The first boot takes a few minutes: the Pi expands the card and"
say "generates its SSH keys. We look for it under the name you gave it in"
say "Raspberry Pi Imager, $PI_NAME, and wait until it accepts SSH connections."
note "(\".local\" names are announced by the Pi itself on your home network.)"
printf '\n'
PI_IP=""
for ((i = 0; i < 60; i++)); do
  PI_IP=$(lookup_ip "$PI_NAME" || true)
  if [[ -n "$PI_IP" ]] && ssh_open "$PI_IP"; then break; fi
  PI_IP=""
  printf '\r  %swaiting for %s … %ss%s ' "$DIM" "$PI_NAME" "$((i * 5))" "$RESET"
  sleep 5
done
printf '\r\033[K'
if [[ -z "$PI_IP" ]]; then
  warn "Couldn't find $PI_NAME after 5 minutes."
  say "Check that the Ethernet cable is in and the green light flickers."
  say "Your router's device list may show it: look for 'jarvis'."
  ask PI_IP "Enter its address from the router (or Ctrl-C to stop):"
  ssh_open "$PI_IP" || { warn "$PI_IP doesn't answer on the SSH port. Re-run when it does."; exit 1; }
fi
PI_MAC=$(mac_of "$PI_IP" || true)
printf '  %s✓ found%s jarvis at %s%s%s' "$GREEN" "$RESET" "$BOLD" "$PI_IP" "$RESET"
[[ -n "$PI_MAC" ]] && printf ', network card (MAC address) %s%s%s' "$BOLD" "$PI_MAC" "$RESET"
printf '\n'
note "The MAC address is the Pi's permanent hardware ID; the router uses it to"
note "recognise the Pi in the next stage."
write_env JARVIS_MAC "$PI_MAC"
pause

# ── 2. DHCP reservation ───────────────────────────────────────────────────
stage "Give the Pi a fixed address in your router"
say "Your router hands out addresses (DHCP) and may give the Pi a different"
say "one some day. A reservation tells it: always give this Pi the same one."
GATEWAY=$(route -n get default 2>/dev/null | awk '/gateway:/ {print $2}' || true)
[[ -z "$GATEWAY" ]] && GATEWAY=$(ip route 2>/dev/null | awk '/^default/ {print $3; exit}' || true)
printf '\n'
if [[ -n "$GATEWAY" ]]; then
  open_url "http://$GATEWAY"
else
  warn "Couldn't work out your router's address; it's usually printed on its label."
fi
step "Log in with the router password (often on a sticker on the router)."
step "Find the DHCP settings. Depending on the router they're under a name"
say  "  like LAN, Home network, DHCP, or Network → Devices. (Menus differ per"
say  "  router model; I can't see yours, so look for these words.)"
step "Find the option to reserve an address, often called 'Address"
say  "  reservation', 'Static DHCP', 'Fixed IP' or 'Always assign this IP'."
step "Pick the device named jarvis${PI_MAC:+ with MAC $PI_MAC}."
step "Reserve its current address, ${BOLD}$PI_IP${RESET}. Keeping the current one"
say  "  is easiest: nothing has to restart. Save."
printf '\n'
ask JARVIS_IP "Which address did you reserve? [$PI_IP]"
[[ -z "$JARVIS_IP" ]] && JARVIS_IP="$PI_IP"
write_env JARVIS_IP "$JARVIS_IP"
if [[ "$JARVIS_IP" != "$PI_IP" ]]; then
  warn "The Pi only picks up a new address when it reconnects."
  say "Unplug the Pi's Ethernet cable, wait 10 seconds, plug it back in."
  note "(Unplugging the cable is safe; pulling the power can damage the card.)"
  printf '\n'
  for ((i = 0; i < 36; i++)); do
    ssh_open "$JARVIS_IP" && break
    printf '\r  %swaiting for jarvis on %s … %ss%s ' "$DIM" "$JARVIS_IP" "$((i * 5))" "$RESET"
    sleep 5
  done
  printf '\r\033[K'
  ssh_open "$JARVIS_IP" || { warn "Nothing answers on $JARVIS_IP yet. Check the reservation, then re-run."; exit 1; }
fi
printf '  %s✓%s jarvis answers on %s\n' "$GREEN" "$RESET" "$JARVIS_IP"
pause

# ── 3. SSH config ─────────────────────────────────────────────────────────
stage "Add 'Host jarvis' to your SSH config"
say "Your SSH config ($SSH_CONFIG) holds shortcuts. With this entry,"
say "'ssh jarvis' means: connect to $JARVIS_IP as your user, with your key."
printf '\n'
ask JARVIS_USER "The username you chose in Raspberry Pi Imager:"
[[ -n "$JARVIS_USER" ]] || { warn "A username is needed."; exit 1; }
write_env JARVIS_USER "$JARVIS_USER"
BLOCK="# jarvis: added by jarvis-wizard.sh
Host jarvis
  HostName $JARVIS_IP
  User $JARVIS_USER
  IdentityFile $SSH_KEY
  IdentitiesOnly yes
  AddKeysToAgent yes"
if [[ "$(uname)" == Darwin ]]; then
  BLOCK+="
  IgnoreUnknown UseKeychain
  UseKeychain yes"
fi
printf '\n%s\n\n' "$BLOCK" | sed 's/^/    /'
note "HostName/User: where and as whom. IdentityFile/IdentitiesOnly: use only"
note "this key. AddKeysToAgent/UseKeychain: remember the unlocked key."
printf '\n'
if confirm "Write this entry to $SSH_CONFIG (replacing any old 'Host jarvis')?"; then
  [[ -e "$SSH_CONFIG" ]] || (umask 077 && : > "$SSH_CONFIG")
  cp "$SSH_CONFIG" "$SSH_CONFIG.bak-jarvis"
  tmp=$(mktemp)
  awk '
    /^# jarvis: added by jarvis-wizard\.sh$/ { next }
    /^[ \t]*(Host|Match)[ \t]/ { skip = ($0 ~ /^[ \t]*Host[ \t]+jarvis[ \t]*$/) }
    !skip
  ' "$SSH_CONFIG" > "$tmp"
  # drop trailing blank lines, then append the block
  sed -e :a -e '/^\n*$/{$d;N;ba' -e '}' "$tmp" > "$tmp.2"
  { cat "$tmp.2"; printf '\n%s\n' "$BLOCK"; } > "$SSH_CONFIG"
  rm -f "$tmp" "$tmp.2"
  printf '  %s✓ wrote%s Host jarvis → %s %s(backup: %s)%s\n' \
    "$GREEN" "$RESET" "$SSH_CONFIG" "$DIM" "$SSH_CONFIG.bak-jarvis" "$RESET"
else
  warn "Skipped. The next stages need this entry; re-run when ready."
  exit 1
fi
pause

# ── 4. Host fingerprint ───────────────────────────────────────────────────
stage "The fingerprint question"
say "The first time you connect, SSH shows something like:"
printf '\n%s    The authenticity of host %s can'"'"'t be established.\n' "$DIM" "$JARVIS_IP"
printf '    ED25519 key fingerprint is SHA256:…\n'
printf '    Are you sure you want to continue connecting (yes/no/[fingerprint])?%s\n\n' "$RESET"
say "Every SSH server has its own key, created on first boot. The fingerprint"
say "is a short summary of it. Answering 'yes' saves it in ~/.ssh/known_hosts."
say "From then on SSH checks it on every connect, and loudly refuses if it"
say "changes, which would mean another device is pretending to be jarvis."
printf '\n'
SCANNED=$(ssh-keyscan -T 5 -t ed25519 "$JARVIS_IP" 2>/dev/null | awk '!/^#/ {print $2, $3}')
PI_FP=$(printf '%s\n' "$SCANNED" | fp_of)
[[ -n "$PI_FP" ]] || { warn "Couldn't read jarvis's host key. Is it still up? Re-run to retry."; exit 1; }
say "jarvis is offering this fingerprint right now:"
printf '\n    %s%s%s\n\n' "$BOLD" "$PI_FP" "$RESET"
KNOWN=$(ssh-keygen -F "$JARVIS_IP" -f "$SSH_DIR/known_hosts" 2>/dev/null \
          | awk '!/^#/ && $2 == "ssh-ed25519" {print $2, $3}' | fp_of || true)
if [[ -n "$KNOWN" ]] && grep -qxF "$PI_FP" <<<"$KNOWN"; then
  printf '  %s✓%s Your Mac already trusts this exact key for %s.\n' "$GREEN" "$RESET" "$JARVIS_IP"
else
  if [[ -n "$KNOWN" ]]; then
    warn "known_hosts holds a DIFFERENT key for $JARVIS_IP."
    say "Expected if you re-flashed the card (new card, new key) or another"
    say "device used this address before. Otherwise, stop and ask for help."
    if confirm "Forget the old key for $JARVIS_IP?"; then
      ssh-keygen -R "$JARVIS_IP" >/dev/null 2>&1
      printf '  %s✓%s removed the old entry (backup: ~/.ssh/known_hosts.old)\n' "$GREEN" "$RESET"
    else
      warn "SSH will refuse to connect until the old entry is gone."; exit 1
    fi
  fi
  say "How sure can you be it's really your Pi? Fully sure only by comparing"
  say "with the Pi's own screen: with a monitor and keyboard attached, log in"
  say "and run: ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub"
  say "Without a screen, on your own home network with a freshly flashed card,"
  say "accepting it is a reasonable risk; that's what most people do."
  printf '\n'
  step "Next, SSH asks the question. Check the fingerprint matches the one above,"
  say  "  then type ${BOLD}yes${RESET} and press Enter."
  note "If SSH asks for a passphrase, that's your key's passphrase, typed into SSH"
  note "itself. It should never ask for a password; if it does, press Ctrl-C."
  pause "Press Enter to connect"
  printf '\n'
  ssh -o StrictHostKeyChecking=ask -o PasswordAuthentication=no \
      -o KbdInteractiveAuthentication=no jarvis exit || true
  printf '\n'
  KNOWN=$(ssh-keygen -F "$JARVIS_IP" -f "$SSH_DIR/known_hosts" 2>/dev/null \
            | awk '!/^#/ && $2 == "ssh-ed25519" {print $2, $3}' | fp_of || true)
  if grep -qxF "$PI_FP" <<<"$KNOWN"; then
    printf '  %s✓%s jarvis'"'"'s fingerprint is saved in known_hosts.\n' "$GREEN" "$RESET"
  else
    warn "The fingerprint wasn't saved (did you answer 'no'?). Re-run to try again."
    exit 1
  fi
fi
pause

# ── 5. Unlock the key ─────────────────────────────────────────────────────
stage "Unlock your SSH key"
say "Your private key ($SSH_KEY) is what proves it's you. A passphrase"
say "keeps it useless to anyone who copies the file. The ssh-agent holds the"
say "unlocked key in memory, so SSH (and Claude Code) can use it without"
say "asking you, and nobody ever needs to see the passphrase."
printf '\n'
[[ -f "$SSH_KEY" ]] || { warn "$SSH_KEY doesn't exist. Create it with: ssh-keygen -t ed25519"; exit 1; }
if ssh-keygen -y -P "" -f "$SSH_KEY" >/dev/null 2>&1; then
  warn "Your key has NO passphrase: anyone who gets a copy of the file can log in."
  say "Adding one doesn't change the public key, so jarvis keeps accepting it."
  if confirm "Add a passphrase now?"; then
    note "ssh-keygen asks for it itself (hidden). It never passes through this script."
    note "Choose something long you'll remember; there's no way to recover it."
    printf '\n'
    ssh-keygen -p -f "$SSH_KEY" || { warn "Passphrase not changed. Re-run to try again."; exit 1; }
  else
    note "Keeping the key without a passphrase."
  fi
  printf '\n'
fi
if [[ "$(uname)" == Darwin ]]; then
  say "On macOS, the passphrase also goes into your Keychain, so the key is"
  say "unlocked automatically after a restart: no ssh-add needed again."
  note "Type the passphrase when ssh-add asks (hidden, read by ssh-add itself)."
  printf '\n'
  /usr/bin/ssh-add --apple-use-keychain "$SSH_KEY" || { warn "ssh-add failed. Re-run to try again."; exit 1; }
else
  note "Type the passphrase when ssh-add asks (hidden, read by ssh-add itself)."
  note "After a restart, run 'ssh-add' again before you start Claude Code."
  printf '\n'
  ssh-add "$SSH_KEY" || { warn "ssh-add failed. Is ssh-agent running? Try: eval \"\$(ssh-agent)\""; exit 1; }
fi
KEY_FP=$(ssh-keygen -lf "$SSH_KEY.pub" | awk '{print $2}')
if ssh-add -l 2>/dev/null | grep -qF "$KEY_FP"; then
  printf '  %s✓%s The agent holds your key (%s).\n' "$GREEN" "$RESET" "$KEY_FP"
else
  warn "The agent doesn't list your key. Re-run this stage."; exit 1
fi
pause

# ── 6. Verify ─────────────────────────────────────────────────────────────
stage "Check key login works and password login is refused"
say "Test 1: log in with the key, with every prompt switched off. If this"
say "works, nothing will ever need to ask you for anything."
printf '\n'
if WHO=$(ssh -o BatchMode=yes jarvis 'echo "$(whoami)@$(hostname)"' 2>/dev/null); then
  printf '  %s✓ key login works:%s %s\n' "$GREEN" "$RESET" "$WHO"
else
  warn "Key login failed. Check the username ($JARVIS_USER) and that Imager got"
  warn "the contents of $SSH_KEY.pub. Details: ssh -v jarvis"
  exit 1
fi
printf '\n'
say "Test 2: try again without the key, the way a password-guesser would, and"
say "read which login methods jarvis offers."
printf '\n'
DENIED=$(ssh -o BatchMode=yes -o PubkeyAuthentication=no -o IdentityAgent=none \
             jarvis true 2>&1 | grep -o 'Permission denied ([^)]*)' || true)
METHODS=$(sed -E 's/.*\((.*)\)/\1/' <<<"$DENIED")
if [[ -z "$DENIED" ]]; then
  warn "Unexpected answer from jarvis. Check by hand: ssh -o PubkeyAuthentication=no jarvis"
  exit 1
elif [[ "$METHODS" == *password* || "$METHODS" == *keyboard-interactive* ]]; then
  warn "jarvis still accepts passwords (offers: $METHODS)."
  say "Imager's 'public-key authentication only' didn't take. Guide step 4 turns"
  say "password login off; tell Claude Code this check failed."
  exit 1
else
  printf '  %s✓ password login refused:%s jarvis only offers %s\n' "$GREEN" "$RESET" "$METHODS"
fi
printf '\n'
printf '  %s%s✓ ssh jarvis works.%s From here on, Claude Code can work on the Pi.\n' "$BOLD" "$GREEN" "$RESET"
pause "Press Enter to finish"

finish
note "Address $JARVIS_IP · user $JARVIS_USER · entry 'Host jarvis' in $SSH_CONFIG"
printf '\n'
}

# mac_ts prints the path of the Mac's tailscale CLI, if Tailscale is installed.
mac_ts() {
  local c
  for c in "$(command -v tailscale 2>/dev/null)" /usr/local/bin/tailscale \
           /Applications/Tailscale.app/Contents/MacOS/Tailscale; do
    [[ -n "$c" && -x "$c" ]] && { printf '%s' "$c"; return 0; }
  done
  return 1
}

tailscale_stages() {

TOTAL_STAGES=6

banner "Reach jarvis from anywhere with Tailscale"

# ── 1. Preflight ──────────────────────────────────────────────────────────
stage "Check that 'ssh jarvis' works"
say "Tailscale gets installed on jarvis over your existing SSH connection,"
say "so that connection has to work first."
printf '\n'
if WHO=$(ssh -o BatchMode=yes -o ConnectTimeout=5 jarvis 'echo "$(whoami)@$(hostname)"' 2>/dev/null); then
  printf '  %s✓ ssh jarvis works:%s %s\n' "$GREEN" "$RESET" "$WHO"
else
  warn "'ssh jarvis' doesn't work yet. Run ./jarvis-wizard.sh connect first,"
  warn "then come back to this stage."
  exit 1
fi
JARVIS_IP=$(_existing JARVIS_IP || true)
JARVIS_USER=$(_existing JARVIS_USER || true)
[[ -n "$JARVIS_IP" && -n "$JARVIS_USER" ]] || { warn "$ENV_FILE is missing JARVIS_IP/JARVIS_USER. Re-run connect."; exit 1; }
if ssh -o BatchMode=yes jarvis 'sudo -n true' 2>/dev/null; then
  note "Your user on jarvis can use sudo without a password, so nothing will ask."
else
  note "sudo on jarvis will ask for your Pi user's password in stages 3 and 4."
fi
pause

# ── 2. Tailscale on the Mac ───────────────────────────────────────────────
stage "Install Tailscale on this Mac"
say "Tailscale builds a private network (a 'tailnet') between your own devices."
say "Both ends need it: this Mac, and jarvis. Your Mac comes first."
printf '\n'
TS=$(mac_ts || true)
if [[ -z "$TS" ]]; then
  open_url "https://tailscale.com/download/mac"
  step "Download and install Tailscale (the Mac App Store version is fine)."
  step "Open it. It sits in the menu bar; click its icon and choose Log in."
  step "Sign in with the account you want to use for jarvis too (Google,"
  say  "  Microsoft, GitHub or Apple). Your tailnet belongs to that account."
  step "Allow the VPN configuration when macOS asks."
  printf '\n'
  pause "Press Enter once the menu bar icon says you're connected"
  TS=$(mac_ts || true)
  [[ -n "$TS" ]] || { warn "Can't find Tailscale in /Applications. Re-run when it's installed."; exit 1; }
fi
MAC_TS_IP=""
for ((i = 0; i < 24; i++)); do
  MAC_TS_IP=$("$TS" ip -4 2>/dev/null | head -n1 || true)
  [[ "$MAC_TS_IP" == 100.* ]] && break
  MAC_TS_IP=""
  printf '\r  %swaiting for Tailscale on this Mac to connect … %ss%s ' "$DIM" "$((i * 5))" "$RESET"
  sleep 5
done
printf '\r\033[K'
if [[ -z "$MAC_TS_IP" ]]; then
  warn "Tailscale on this Mac isn't connected. Log in from the menu bar icon, then re-run."
  exit 1
fi
printf '  %s✓ this Mac is on your tailnet%s as %s\n' "$GREEN" "$RESET" "$MAC_TS_IP"
note "Tailscale addresses start with 100. Only your own devices can reach them."
pause

# ── 3. Install on jarvis ──────────────────────────────────────────────────
stage "Install Tailscale on jarvis"
if VER=$(ssh -o BatchMode=yes jarvis 'tailscale version 2>/dev/null | head -n1') && [[ -n "$VER" ]]; then
  printf '  %s✓ already installed%s on jarvis (version %s)\n' "$GREEN" "$RESET" "$VER"
else
  say "This runs Tailscale's official install script on jarvis:"
  printf '\n    %scurl -fsSL https://tailscale.com/install.sh | sh%s\n\n' "$BOLD" "$RESET"
  say "It adds Tailscale's package source to apt and installs the 'tailscale'"
  say "package, so the normal automatic updates keep it current. It takes a"
  say "minute or two on a Pi 3."
  printf '\n'
  confirm "Install Tailscale on jarvis now?" || { warn "Skipped. Re-run when ready."; exit 1; }
  printf '\n'
  ssh -t jarvis 'curl -fsSL https://tailscale.com/install.sh | sh' \
    || { warn "The install failed; the output above says why. Re-run to try again."; exit 1; }
  VER=$(ssh -o BatchMode=yes jarvis 'tailscale version 2>/dev/null | head -n1' || true)
  [[ -n "$VER" ]] || { warn "tailscale isn't on jarvis after the install. Re-run to try again."; exit 1; }
  printf '\n  %s✓ installed%s Tailscale %s on jarvis\n' "$GREEN" "$RESET" "$VER"
fi
pause

# ── 4. Log jarvis in ──────────────────────────────────────────────────────
stage "Add jarvis to your tailnet"
JARVIS_TS_IP=$(ssh -o BatchMode=yes jarvis 'tailscale ip -4 2>/dev/null | head -n1' || true)
if [[ "$JARVIS_TS_IP" == 100.* ]]; then
  printf '  %s✓ jarvis is already on your tailnet%s as %s\n' "$GREEN" "$RESET" "$JARVIS_TS_IP"
else
  say "jarvis now asks Tailscale for a login link. I open it in your browser;"
  say "there you approve jarvis as one of your devices."
  printf '\n'
  step "Sign in with the ${BOLD}same account${RESET} you used on this Mac."
  step "Click Connect. Back here, jarvis finishes logging in by itself."
  note "The link only adds a device; it's not a password. It expires after a while."
  printf '\n'
  pause "Press Enter to get the link"
  UP_LOG=$(mktemp)
  # Watch tailscale up's output for the login link and open it here on the Mac.
  ( for ((i = 0; i < 120; i++)); do
      URL=$(grep -oE 'https://login\.tailscale\.com/[^[:space:]]+' "$UP_LOG" | head -n1 || true)
      [[ -n "$URL" ]] && { open_url "$URL"; break; }
      sleep 1
    done ) &
  WATCHER=$!
  ssh -t jarvis 'sudo tailscale up' 2>&1 | tee "$UP_LOG" || true
  kill "$WATCHER" 2>/dev/null || true
  rm -f "$UP_LOG"
  JARVIS_TS_IP=$(ssh -o BatchMode=yes jarvis 'tailscale ip -4 2>/dev/null | head -n1' || true)
  [[ "$JARVIS_TS_IP" == 100.* ]] || { warn "jarvis didn't get a Tailscale address. Re-run to try again."; exit 1; }
  printf '\n  %s✓ jarvis joined your tailnet%s as %s\n' "$GREEN" "$RESET" "$JARVIS_TS_IP"
fi
write_env JARVIS_TS_IP "$JARVIS_TS_IP"
pause

# ── 5. Key expiry ─────────────────────────────────────────────────────────
stage "Keep jarvis logged in"
say "Tailscale makes every device log in again after 180 days. For a laptop"
say "that's a good safety net. For a Pi with no screen it means jarvis silently"
say "drops off your tailnet one day, when you may be away from home."
printf '\n'
open_url "https://login.tailscale.com/admin/machines"
step "On the Machines page, find the row for ${BOLD}jarvis${RESET} ($JARVIS_TS_IP)."
step "Click the ⋯ menu at the far right of that row."
step "Choose ${BOLD}Disable key expiry${RESET}. The row then shows 'Expiry disabled'."
note "Only do this for jarvis, a device you control. Keep it on for everything else."
printf '\n'
pause "Press Enter once key expiry is disabled"

# ── 6. SSH over Tailscale ─────────────────────────────────────────────────
stage "Add 'Host jarvis-ts' and test SSH over Tailscale"
say "'ssh jarvis' keeps using the home address. 'ssh jarvis-ts' goes over"
say "Tailscale, so it works wherever you are, as long as Tailscale runs on this Mac."
printf '\n'
BLOCK="# jarvis-ts: added by jarvis-wizard.sh
Host jarvis-ts
  HostName $JARVIS_TS_IP
  HostKeyAlias $JARVIS_IP
  User $JARVIS_USER
  IdentityFile $SSH_KEY
  IdentitiesOnly yes
  AddKeysToAgent yes"
if [[ "$(uname)" == Darwin ]]; then
  BLOCK+="
  IgnoreUnknown UseKeychain
  UseKeychain yes"
fi
printf '\n%s\n\n' "$BLOCK" | sed 's/^/    /'
note "HostKeyAlias: check jarvis against the fingerprint you already verified"
note "in the connect stage, so SSH doesn't ask the fingerprint question again."
printf '\n'
if confirm "Write this entry to $SSH_CONFIG (replacing any old 'Host jarvis-ts')?"; then
  cp "$SSH_CONFIG" "$SSH_CONFIG.bak-jarvis-ts"
  tmp=$(mktemp)
  awk '
    /^# jarvis-ts: added by jarvis-wizard\.sh$/ { next }
    /^[ \t]*(Host|Match)[ \t]/ { skip = ($0 ~ /^[ \t]*Host[ \t]+jarvis-ts[ \t]*$/) }
    !skip
  ' "$SSH_CONFIG" > "$tmp"
  # drop trailing blank lines, then append the block
  sed -e :a -e '/^\n*$/{$d;N;ba' -e '}' "$tmp" > "$tmp.2"
  { cat "$tmp.2"; printf '\n%s\n' "$BLOCK"; } > "$SSH_CONFIG"
  rm -f "$tmp" "$tmp.2"
  printf '  %s✓ wrote%s Host jarvis-ts → %s %s(backup: %s)%s\n' \
    "$GREEN" "$RESET" "$SSH_CONFIG" "$DIM" "$SSH_CONFIG.bak-jarvis-ts" "$RESET"
else
  warn "Skipped. Re-run when ready."
  exit 1
fi
printf '\n'
say "Test: log in over Tailscale with every prompt switched off."
printf '\n'
if WHO=$(ssh -o BatchMode=yes -o ConnectTimeout=10 jarvis-ts 'echo "$(whoami)@$(hostname)"' 2>/dev/null); then
  printf '  %s✓ ssh over Tailscale works:%s %s\n' "$GREEN" "$RESET" "$WHO"
else
  warn "SSH over Tailscale failed. Check that both devices show as connected on"
  warn "the Machines page. Details: ssh -v jarvis-ts"
  exit 1
fi
printf '\n'
printf '  %s%s✓ ssh jarvis-ts works.%s Away from home, use it instead of ssh jarvis.\n' "$BOLD" "$GREEN" "$RESET"
pause "Press Enter to finish"

finish
note "jarvis on Tailscale: $JARVIS_TS_IP · entry 'Host jarvis-ts' in $SSH_CONFIG"
printf '\n'
}

# The three values Hermes reads from its secrets file, /home/hermes/.hermes/.env.
HERMES_ENV=/home/hermes/.hermes/.env
SECRET_KEYS=(TELEGRAM_BOT_TOKEN TELEGRAM_ALLOWED_USERS OPENROUTER_API_KEY)

# tg_api METHOD calls the Telegram Bot API. The token travels to curl on stdin
# (curl -K -), never as an argument, so it never shows up in the process list.
tg_api() {
  printf 'url = "https://api.telegram.org/bot%s/%s"\n' "$TELEGRAM_BOT_TOKEN" "$1" \
    | curl -sS --max-time 20 -K - 2>/dev/null || true
}

# or_key_info asks OpenRouter about the key itself (label, limit), key on stdin.
or_key_info() {
  printf 'url = "https://openrouter.ai/api/v1/key"\nheader = "Authorization: Bearer %s"\n' \
    "$OPENROUTER_API_KEY" | curl -sS --max-time 20 -K - 2>/dev/null || true
}

# pi_sudo makes sure the admin login on jarvis is fresh (sudo -v). If it has
# expired, sudo on jarvis asks for your password itself; this script never sees it.
pi_sudo() {
  ssh -o BatchMode=yes jarvis 'sudo -n true' 2>/dev/null && return 0
  say "jarvis needs your admin password (the one you set in Raspberry Pi Imager)."
  note "You type it into sudo on jarvis directly; this script never sees it."
  ssh -t jarvis 'sudo -v' || { warn "sudo failed. Re-run when ready."; exit 1; }
}

# The script that runs on jarvis as the hermes user. It reads KEY=value lines on
# stdin and replaces just those keys in the secrets file, keeping everything else.
# It never prints a value.
read -r -d '' REMOTE_WRITE <<'REMOTE' || true
set -eu
f=/home/hermes/.hermes/.env
umask 077
[ -f "$f" ] || { echo "no secrets file at $f" >&2; exit 3; }
lines=()
while IFS= read -r line; do
  case "$line" in
    TELEGRAM_BOT_TOKEN=?*|TELEGRAM_ALLOWED_USERS=?*|OPENROUTER_API_KEY=?*) lines+=("$line") ;;
    *) echo "unexpected input line, nothing written" >&2; exit 4 ;;
  esac
done
[ "${#lines[@]}" -gt 0 ] || { echo "nothing to write"; exit 0; }
names=$(printf '%s\n' "${lines[@]}" | cut -d= -f1 | paste -sd'|' -)
tmp=$(mktemp "$f.XXXXXX")
grep -v -E "^($names)=" "$f" > "$tmp" || true
printf '%s\n' "${lines[@]}" >> "$tmp"
chmod 600 "$tmp"
mv "$tmp" "$f"
echo "wrote ${#lines[@]} value(s)"
REMOTE

# The check that runs on jarvis as hermes: owner, mode, and which names are set.
read -r -d '' REMOTE_CHECK <<'REMOTE' || true
f=/home/hermes/.hermes/.env
stat -c 'owner=%U mode=%a' "$f"
for k in TELEGRAM_BOT_TOKEN TELEGRAM_ALLOWED_USERS OPENROUTER_API_KEY; do
  grep -qE "^$k=." "$f" && echo "$k=set" || echo "$k=missing"
done
REMOTE

secrets_stages() {

TOTAL_STAGES=6

banner "Telegram bot and keys for Jarvis"

# ── 1. Preflight ──────────────────────────────────────────────────────────
stage "Check jarvis and the secrets file"
say "This stage collects three things and puts them in Hermes's secrets file"
say "on jarvis, $HERMES_ENV:"
step "TELEGRAM_BOT_TOKEN: the password of Jarvis's Telegram bot (secret)"
step "TELEGRAM_ALLOWED_USERS: your Telegram user ID, the only one Jarvis answers"
step "OPENROUTER_API_KEY: Jarvis's own OpenRouter key (secret)"
printf '\n'
say "How the secrets move: you paste them at hidden prompts. They stay in this"
say "script's memory, go to Telegram/OpenRouter only to check they work, then"
say "travel over SSH (encrypted) on the input stream, never on a command line,"
say "into the file, which only the hermes user can read. Nothing is written to"
say "your Mac's disk, and nothing secret is printed."
printf '\n'
for tool in curl jq; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing on this Mac."; exit 1; }
done
if ! ssh -o BatchMode=yes -o ConnectTimeout=5 jarvis true 2>/dev/null; then
  warn "'ssh jarvis' doesn't work. Run ./jarvis-wizard.sh connect first."; exit 1
fi
pi_sudo
STATUS=$(ssh -o BatchMode=yes jarvis "cd / && sudo -n -u hermes bash -c $(printf %q "$REMOTE_CHECK")" 2>/dev/null || true)
if [[ "$STATUS" != owner=hermes* ]]; then
  warn "Can't find Hermes's secrets file on jarvis. Is Hermes installed (step 8)?"; exit 1
fi
HAVE=()
for k in "${SECRET_KEYS[@]}"; do grep -qx "$k=set" <<<"$STATUS" && HAVE+=("$k"); done
printf '  %s✓%s found %s (%s)\n' "$GREEN" "$RESET" "$HERMES_ENV" "$(head -1 <<<"$STATUS")"
(( ${#HAVE[@]} )) && note "Already set on jarvis: ${HAVE[*]}. Press Enter at a prompt to keep one."
pause

# has_key NAME: is NAME already set on jarvis?
has_key() { local k; for k in ${HAVE[@]+"${HAVE[@]}"}; do [[ "$k" == "$1" ]] && return 0; done; return 1; }
SEND=()

# ── 2. Telegram bot token ─────────────────────────────────────────────────
stage "Create Jarvis's Telegram bot"
say "Telegram bots are made by chatting with @BotFather, Telegram's official"
say "bot for creating bots. The token it gives you is the bot's password."
printf '\n'
open_url "https://t.me/BotFather"
step "In Telegram, send /newbot to BotFather."
step "Give it a display name, e.g. Jarvis."
step "Give it a username ending in 'bot', e.g. jarvis_$(id -un | tr -cd 'a-z0-9')_bot."
step "Copy the token from the reply (the long line with a colon in it)."
printf '\n'
TELEGRAM_BOT_TOKEN=""
while :; do
  ask_secret TELEGRAM_BOT_TOKEN "Paste the bot token (hidden):"
  if [[ -z "$TELEGRAM_BOT_TOKEN" ]] && has_key TELEGRAM_BOT_TOKEN; then
    note "Keeping the token already on jarvis."; break
  fi
  if [[ ! "$TELEGRAM_BOT_TOKEN" =~ ^[0-9]{6,12}:[A-Za-z0-9_-]{30,}$ ]]; then
    warn "That doesn't look like a bot token (digits, a colon, then ~35 characters). Try again."
    continue
  fi
  ME=$(tg_api getMe)
  if [[ "$(jq -r '.ok' <<<"$ME" 2>/dev/null)" == true ]]; then
    BOT_USERNAME=$(jq -r '.result.username' <<<"$ME")
    printf '  %s✓ Telegram accepts the token:%s the bot is @%s\n' "$GREEN" "$RESET" "$BOT_USERNAME"
    SEND+=("TELEGRAM_BOT_TOKEN=$TELEGRAM_BOT_TOKEN")
    break
  fi
  warn "Telegram rejected that token. Copy it again from BotFather's reply."
done
printf '\n'
say "Now stop strangers from adding Jarvis to group chats:"
step "Send /setjoingroups to BotFather, pick the bot, choose Disable."
pause "Press Enter when BotFather confirms"

# ── 3. Telegram user ID ───────────────────────────────────────────────────
stage "Find your Telegram user ID"
say "Jarvis will only answer this number. Every Telegram account has one; the"
say "easiest way to get yours is to message your new bot and read it from there."
printf '\n'
TG_ID=""
SAVED_ID=$(_existing TELEGRAM_ALLOWED_USERS || true)
if [[ -n "$SAVED_ID" ]] && confirm "Use your saved Telegram ID $SAVED_ID?"; then
  TG_ID="$SAVED_ID"
elif [[ -n "$TELEGRAM_BOT_TOKEN" ]]; then
  open_url "https://t.me/$BOT_USERNAME"
  step "In Telegram, open @$BOT_USERNAME, press Start (or send 'hi')."
  note "The bot won't answer yet; Hermes isn't connected until step 10."
  printf '\n'
  FOUND=""
  for ((i = 0; i < 45; i++)); do
    UPD=$(tg_api "getUpdates?timeout=0")
    FOUND=$(jq -r '[.result[]? | select(.message.chat.type == "private") | .message.from]
                   | last // empty | "\(.id)\t\(.first_name // "")\t\(.username // "")"' <<<"$UPD" 2>/dev/null || true)
    [[ -n "$FOUND" ]] && break
    printf '\r  %swaiting for your message … %ss%s ' "$DIM" "$((i * 2))" "$RESET"
    sleep 2
  done
  printf '\r\033[K'
  if [[ -n "$FOUND" ]]; then
    IFS=$'\t' read -r F_ID F_NAME F_USER <<<"$FOUND"
    if confirm "Is this you: $F_NAME${F_USER:+ (@$F_USER)}, ID $F_ID?"; then TG_ID="$F_ID"; fi
    # Mark the messages as read, so Hermes doesn't answer them later.
    LAST=$(jq -r '.result | last | .update_id // empty' <<<"$UPD" 2>/dev/null || true)
    [[ -n "$LAST" ]] && tg_api "getUpdates?offset=$((LAST + 1))&timeout=0" >/dev/null
  else
    warn "No message arrived."
  fi
fi
while [[ ! "$TG_ID" =~ ^[0-9]{4,15}$ ]]; do
  say "Enter it by hand instead: in Telegram, message @userinfobot; it replies"
  say "with your ID (a number)."
  ask TELEGRAM_ALLOWED_USERS "Your Telegram user ID:"
  TG_ID="$TELEGRAM_ALLOWED_USERS"
done
write_env TELEGRAM_ALLOWED_USERS "$TG_ID"
SEND+=("TELEGRAM_ALLOWED_USERS=$TG_ID")
pause

# ── 4. OpenRouter key ─────────────────────────────────────────────────────
stage "Create Jarvis's OpenRouter key"
say "Jarvis gets its own key with its own spending limit, separate from Claude"
say "Code's. If Jarvis loops or the key leaks, it can spend at most this limit,"
say "and you can revoke it without touching anything else."
printf '\n'
open_url "https://openrouter.ai/settings/keys"
step "Click 'Create API Key' (wording may differ slightly)."
step "Name: ${BOLD}jarvis${RESET}"
step "Credit limit: ${BOLD}5${RESET} (US dollars). If there's a reset option, choose monthly."
step "Create it, then copy the key (starts with sk-or-). It's only shown once."
printf '\n'
OPENROUTER_API_KEY=""
while :; do
  ask_secret OPENROUTER_API_KEY "Paste the OpenRouter key (hidden):"
  if [[ -z "$OPENROUTER_API_KEY" ]] && has_key OPENROUTER_API_KEY; then
    note "Keeping the key already on jarvis."; break
  fi
  if [[ ! "$OPENROUTER_API_KEY" =~ ^sk-or-[A-Za-z0-9_-]{20,}$ ]]; then
    warn "That doesn't look like an OpenRouter key (starts with sk-or-). Try again."
    continue
  fi
  INFO=$(or_key_info)
  if jq -e '.data' <<<"$INFO" >/dev/null 2>&1; then
    OR_LABEL=$(jq -r '.data.label // "?"' <<<"$INFO")
    OR_LIMIT=$(jq -r '.data.limit // "none"' <<<"$INFO")
    OR_RESET=$(jq -r '.data.limit_reset // "never"' <<<"$INFO")
    printf '  %s✓ OpenRouter accepts the key%s (label: %s, limit: %s, resets: %s)\n' \
      "$GREEN" "$RESET" "$OR_LABEL" "$OR_LIMIT" "$OR_RESET"
    [[ "$OR_LIMIT" == none ]] && warn "This key has NO credit limit. Set one on the Keys page before you go on."
    SEND+=("OPENROUTER_API_KEY=$OPENROUTER_API_KEY")
    break
  fi
  warn "OpenRouter rejected that key. Copy it again (or create a new one)."
done
pause

# ── 5. Send to jarvis ─────────────────────────────────────────────────────
stage "Store the secrets on jarvis"
if (( ${#SEND[@]} == 0 )); then
  note "Nothing new to store."
else
  say "Next: SSH opens an encrypted connection to jarvis and runs a small fixed"
  say "script as the hermes user. The values go in on its input stream, so they"
  say "never appear on a command line or in a log. The script replaces only these"
  say "lines in $HERMES_ENV and keeps the file at mode 600."
  printf '\n'
  for kv in "${SEND[@]}"; do step "${kv%%=*}"; done
  printf '\n'
  if ! confirm "Write these to jarvis?"; then warn "Nothing written. Re-run when ready."; exit 1; fi
  pi_sudo
  if OUT=$(printf '%s\n' "${SEND[@]}" \
        | ssh -o BatchMode=yes jarvis "cd / && sudo -n -u hermes bash -c $(printf %q "$REMOTE_WRITE")" 2>&1); then
    printf '  %s✓%s jarvis: %s\n' "$GREEN" "$RESET" "$OUT"
  else
    warn "Writing failed: $OUT"; exit 1
  fi
fi
unset TELEGRAM_BOT_TOKEN OPENROUTER_API_KEY SEND
pause

# ── 6. Verify ─────────────────────────────────────────────────────────────
stage "Check the secrets file"
say "Checking by name only: owner, permissions, and which keys are set."
printf '\n'
STATUS=$(ssh -o BatchMode=yes jarvis "cd / && sudo -n -u hermes bash -c $(printf %q "$REMOTE_CHECK")" 2>/dev/null || true)
OK=true
if grep -qx 'owner=hermes mode=600' <<<"$(head -1 <<<"$STATUS")"; then
  printf '  %s✓%s owned by hermes, mode 600 (only hermes can read it)\n' "$GREEN" "$RESET"
else
  warn "Unexpected owner/mode: $(head -1 <<<"$STATUS")"; OK=false
fi
for k in "${SECRET_KEYS[@]}"; do
  if grep -qx "$k=set" <<<"$STATUS"; then printf '  %s✓%s %s is set\n' "$GREEN" "$RESET" "$k"
  else warn "$k is missing"; OK=false; fi
done
if ssh -o BatchMode=yes jarvis "test -r $HERMES_ENV" 2>/dev/null; then
  warn "Your own user on jarvis can read the file. It shouldn't."; OK=false
else
  printf '  %s✓%s your admin user can'"'"'t read it without sudo\n' "$GREEN" "$RESET"
fi
$OK || exit 1
printf '\n'
printf '  %s%s✓ Secrets are in place.%s Next, Claude Code connects Hermes to Telegram (step 10).\n' "$BOLD" "$GREEN" "$RESET"
pause "Press Enter to finish"

finish
}

case "${1:-}" in
  connect) connect ;;
  tailscale) tailscale_stages ;;
  secrets) secrets_stages ;;
  *) usage; [[ -z "${1:-}" ]] && exit 0 || exit 1 ;;
esac
}

run_wizard "$@"; exit
